import{_ as e,o as a,c as n,a2 as t}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"Overview","description":"One command, two modes. Invoke-AzureScout runs the inventory, the CAF/WAF assessment, or both — with a guided wizard if you run it with no parameters.","frontmatter":{"description":"One command, two modes. Invoke-AzureScout runs the inventory, the CAF/WAF assessment, or both — with a guided wizard if you run it with no parameters."},"headers":[],"relativePath":"guide/overview.md","filePath":"guide/overview.md"}'),i={name:"guide/overview.md"};function o(l,s,r,p,d,h){return a(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p>AzureScout is <strong>one command</strong>: <code>Invoke-AzureScout</code>.</p><p>It has two modes. Inventory tells you <em>what&#39;s in your tenant</em>. Assessment scores that estate against Microsoft&#39;s Cloud Adoption Framework and Well-Architected Framework. You pick a mode with a switch — not with a different tool.</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Install-Module</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Name AzureScout</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Connect-AzAccount</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                              # guided wizard — pick everything from a menu</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NoWizard                    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># inventory, default settings</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment LandingZone      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># CAF/WAF assessment</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="just-run-it" tabindex="-1">Just run it <a class="header-anchor" href="#just-run-it" aria-label="Permalink to &quot;Just run it&quot;">​</a></h2><p>Run <code>Invoke-AzureScout</code> with no parameters and you get a wizard. It signs you in, checks the account actually holds the rights the scan needs, then hands you a checklist of everything Scout can do — all of it pre-selected, so you uncheck what you don&#39;t want:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  Step 3/5 — What to run</span></span>
<span class="line"><span>  ────────────────────────────────────────────────────────</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Resource categories to inventory</span></span>
<span class="line"><span>    [x]  1. AI</span></span>
<span class="line"><span>    [x]  2. Analytics</span></span>
<span class="line"><span>    [x]  3. Compute</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   Toggle with numbers (e.g. &quot;3&quot; or &quot;3,5,9&quot;), a = all, n = none,</span></span>
<span class="line"><span>   Enter = accept, q = quit</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>The last step prints the equivalent one-line command, so the wizard also teaches you the parameters for when you want to script it later.</p><p>The wizard <strong>only</strong> opens in an interactive session. CI, scheduled tasks, containers, and anything with redirected input fall straight through to the default inventory run — a bare <code>Invoke-AzureScout</code> in a pipeline can never block on a prompt. Use <code>-NoWizard</code> to force that same behaviour at a terminal.</p><h2 id="the-two-modes" tabindex="-1">The two modes <a class="header-anchor" href="#the-two-modes" aria-label="Permalink to &quot;The two modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">Inventory (default)</th><th style="text-align:left;">Assessment (<code>-Assessment</code>)</th></tr></thead><tbody><tr><td style="text-align:left;">Answers</td><td style="text-align:left;">&quot;What&#39;s in my tenant?&quot;</td><td style="text-align:left;">&quot;How well does it conform to CAF/WAF?&quot;</td></tr><tr><td style="text-align:left;">Output</td><td style="text-align:left;">Excel, JSON, Markdown, AsciiDoc, Power BI CSVs</td><td style="text-align:left;">Scored <code>findings.json</code>, HTML, Power BI, PowerPoint, React, Excel evidence</td></tr><tr><td style="text-align:left;"><code>-OutputFormat</code></td><td style="text-align:left;"><code>All</code>, <code>Excel</code>, <code>Json</code>, <code>Markdown</code>, <code>AsciiDoc</code>, <code>PowerBI</code></td><td style="text-align:left;"><code>Html</code>, <code>Pptx</code>, <code>React</code>, <code>Pdf</code>, <code>Word</code>, <code>EChartsDashboard</code>, <code>JsonEvidence</code>, plus <code>Excel</code>/<code>Json</code>/<code>PowerBI</code></td></tr><tr><td style="text-align:left;">Full guide</td><td style="text-align:left;"><a href="./usage.html">Usage Guide</a></td><td style="text-align:left;"><a href="./../assessment/assessment.html">Assessment mode</a></td></tr></tbody></table><p>Both modes are the same module, the same sign-in, and the same <code>-TenantID</code>, <code>-Scope</code>, <code>-Category</code>, and <code>-ReportDir</code> parameters. Mixing a format across modes fails with a message telling you which switch you actually wanted, rather than quietly producing nothing.</p><h2 id="running-both" tabindex="-1">Running both <a class="header-anchor" href="#running-both" aria-label="Permalink to &quot;Running both&quot;">​</a></h2><p>An assessment scores your estate, so it needs to know what&#39;s in it. To get the raw inventory <em>and</em> the scored analysis from a single run — and a single collection from Azure — add <code>-InventoryAndAssessment</code> (alias <code>-Both</code>) alongside <code>-Assessment</code>:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment LandingZone </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">InventoryAndAssessment </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ReportDir .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scout</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The wizard&#39;s <strong>Both</strong> choice sets the same switch behind the scenes. Before this switch existed, the collect-once path was reachable only by answering that wizard prompt — a script or CI pipeline had no equivalent, and had to invoke the command twice back to back:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ReportDir .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scout                          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># inventory — collects from Azure</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment LandingZone </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ReportDir .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scout  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># assessment — collects again</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>That still works, but it pays for two collections against Azure instead of one.</p><div class="tip custom-block"><p class="custom-block-title">One collection pass</p><p>The inventory pass already fetches the full property bag for every resource, and the assessment shapes its scores from those rows instead of re-querying the same resource types. Exactly one Resource Graph query still runs in a combined pass — the Defender for SQL pricing lookup, which reads a table the inventory does not collect. An assessment-only run is unchanged and still issues the full query pack.</p></div><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p><strong>PowerShell 7.0 or later, on PowerShell Core.</strong> That applies to the whole module, both modes — <code>AzureScout.psd1</code> declares <code>PowerShellVersion = &#39;7.0&#39;</code> and <code>CompatiblePSEditions = @(&#39;Core&#39;)</code>, so <code>Import-Module</code> rejects Windows PowerShell 5.1 outright.</p><p>See <a href="./prerequisites.html">Prerequisites &amp; Required Modules</a> for the module list, and <a href="./../assessment/assessment-prerequisites.html">Assessment Prerequisites</a> for the extra dependencies the PowerPoint and PDF report tiers need.</p><h2 id="assessment-command-migration" tabindex="-1">Assessment command migration <a class="header-anchor" href="#assessment-command-migration" aria-label="Permalink to &quot;Assessment command migration&quot;">​</a></h2><p>The former standalone assessment command was a second entry point in v2.3.0 and earlier. It was removed in v3.0.0. Use the unified switch:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Before</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment LandingZone </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputFormat Html</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># After</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Assessment LandingZone </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputFormat Html</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Every parameter maps across unchanged, except <code>-OutputPath</code>, which is <code>-ReportDir</code> on <code>Invoke-AzureScout</code>.</p><div class="tip custom-block"><p class="custom-block-title">Next steps</p><ul><li><a href="./prerequisites.html">Prerequisites &amp; Required Modules</a> — what to install first.</li><li><a href="./usage.html">Usage Guide</a> — inventory mode in depth.</li><li><a href="./../assessment/assessment.html">Assessment mode</a> — the CAF/WAF rules, scoring, and report tiers.</li><li><a href="./parameters.html">Parameters Reference</a> — every switch on the one command.</li></ul></div>`,27)])])}const k=e(i,[["render",o]]);export{u as __pageData,k as default};
